CREATE TRIGGER account_privacy_birth_immutable BEFORE UPDATE OF birth_date ON account_privacy WHEN OLD.birth_date IS NOT NULL AND NEW.birth_date IS NOT NULL AND NEW.birth_date<>OLD.birth_date BEGIN SELECT RAISE(ABORT,'PRIVACY_BIRTH_IMMUTABLE'); END;
